import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, NavLink, useLocation, Navigate } from 'react-router-dom';
import { 
  LayoutDashboard, 
  Map as MapIcon, 
  Bell, 
  Search,
  Box,
  Activity,
  LogOut
} from 'lucide-react';

import Dashboard from './pages/Dashboard';
import FleetMap from './pages/FleetMap';
import WarehouseOps from './pages/WarehouseOps';
import AnalyticsReport from './pages/AnalyticsReport';

import { INITIAL_VEHICLES, MOCK_WAREHOUSES, INITIAL_ROUTES } from './constants';
import { Vehicle, VehicleStatus } from './types';
import { getRouteOptimization } from './services/geminiService';

const Layout: React.FC<{ children: React.ReactNode, currentTime: Date }> = ({ children, currentTime }) => {
  const location = useLocation();

  const getTitle = () => {
    switch(location.pathname) {
      case '/': return 'Command Center';
      case '/map': return 'Fleet Surveillance';
      case '/warehouse': return 'Warehouse Operations';
      case '/analytics': return 'Intelligence Report';
      default: return 'LogiFlow AI';
    }
  };

  return (
    <div className="min-h-screen bg-[#0C1114] text-gray-300 font-sans selection:bg-neon selection:text-black flex overflow-hidden">
      {/* Sidebar */}
      <aside className="w-20 lg:w-64 border-r border-gray-800 flex flex-col justify-between bg-[#080a0c] z-20 hidden md:flex transition-all duration-300">
        <div>
          <div className="h-16 flex items-center px-6 border-b border-gray-800">
            <div className="w-8 h-8 bg-neon rounded-lg flex items-center justify-center shadow-[0_0_15px_#72FF72]">
               <Box className="text-black w-5 h-5" />
            </div>
            <span className="ml-3 font-display font-bold text-xl text-white tracking-tight hidden lg:block">
              LogiFlow<span className="text-neon">.AI</span>
            </span>
          </div>

          <nav className="p-4 space-y-2">
            <NavItem to="/" icon={LayoutDashboard} label="Dashboard" />
            <NavItem to="/map" icon={MapIcon} label="Fleet Map" />
            <NavItem to="/warehouse" icon={Box} label="Warehouse" />
            <NavItem to="/analytics" icon={Activity} label="Analytics" />
          </nav>
        </div>

        <div className="p-4 border-t border-gray-800">
           <div className="flex items-center gap-3 p-2 rounded hover:bg-gray-800 cursor-pointer group">
              <div className="w-8 h-8 rounded-full bg-gray-700 flex items-center justify-center text-white group-hover:bg-gray-600">
                  OP
              </div>
              <div className="hidden lg:block">
                 <p className="text-sm text-white font-medium">Ops Director</p>
                 <p className="text-xs text-gray-500">admin@logiflow.ai</p>
              </div>
              <LogOut className="w-4 h-4 text-gray-500 ml-auto hidden lg:block hover:text-white" />
           </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
         {/* Top Bar */}
         <header className="h-16 border-b border-gray-800 flex items-center justify-between px-6 bg-[#0C1114]/80 backdrop-blur z-10">
            <div className="flex items-center gap-4">
               <div className="md:hidden text-neon font-bold">LF.AI</div>
               <h1 className="font-display font-bold text-white text-lg hidden md:block">{getTitle()}</h1>
            </div>

            <div className="flex items-center gap-2 md:gap-6">
               <div className="hidden md:flex items-center bg-gray-900 border border-gray-700 rounded px-3 py-1.5">
                   <Search className="w-4 h-4 text-gray-500 mr-2" />
                   <input 
                     type="text" 
                     placeholder="Search fleet ID..." 
                     className="bg-transparent border-none outline-none text-sm w-48 focus:text-white placeholder-gray-600"
                   />
               </div>

               <div className="flex items-center gap-4">
                   <div className="text-right hidden sm:block">
                      <p className="text-xs font-mono text-neon">{currentTime.toLocaleTimeString()}</p>
                      <p className="text-[10px] font-mono text-gray-500">{currentTime.toLocaleDateString()}</p>
                   </div>
                   <button className="p-2 rounded-full hover:bg-gray-800 text-gray-400 hover:text-white relative">
                      <Bell className="w-5 h-5" />
                      <span className="absolute top-1 right-1 w-2 h-2 bg-danger rounded-full animate-pulse"></span>
                   </button>
                </div>
            </div>
         </header>

         {/* Content Scroll Area */}
         <div className="flex-1 overflow-y-auto p-4 lg:p-6">
            {children}
         </div>
      </main>
    </div>
  );
};

const NavItem: React.FC<{ to: string, icon: any, label: string }> = ({ to, icon: Icon, label }) => (
  <NavLink 
    to={to}
    className={({ isActive }) => `
      flex items-center gap-3 px-4 py-3 rounded-lg cursor-pointer transition-all duration-200
      ${isActive 
        ? 'bg-gray-800/80 text-white border-r-2 border-neon shadow-[0_0_10px_rgba(0,0,0,0.3)]' 
        : 'text-gray-500 hover:text-gray-300 hover:bg-gray-800/50'}
    `}
  >
    <Icon className="w-5 h-5" />
    <span className="font-medium text-sm hidden lg:block">{label}</span>
  </NavLink>
);

const App: React.FC = () => {
  const [vehicles, setVehicles] = useState<Vehicle[]>(INITIAL_VEHICLES);
  const [selectedVehicleId, setSelectedVehicleId] = useState<string | undefined>(undefined);
  const [currentTime, setCurrentTime] = useState(new Date());
  const [aiAdvice, setAiAdvice] = useState<string | null>(null);
  const [optimizing, setOptimizing] = useState(false);

  // Simulate clock
  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  // Simulate vehicle movement
  useEffect(() => {
    const moveTimer = setInterval(() => {
      setVehicles(prev => prev.map(v => {
        if (v.status !== VehicleStatus.ACTIVE) return v;

        const jitterX = (Math.random() - 0.5) * 1;
        const jitterY = (Math.random() - 0.5) * 1;

        const newFuel = v.fuelLevel - (Math.random() * 0.05);

        return {
          ...v,
          coordinates: {
            x: Math.min(95, Math.max(5, v.coordinates.x + jitterX)),
            y: Math.min(95, Math.max(5, v.coordinates.y + jitterY))
          },
          fuelLevel: Math.max(0, Number(newFuel.toFixed(1)))
        };
      }));
    }, 2000);
    return () => clearInterval(moveTimer);
  }, []);

  const handleVehicleSelect = (v: Vehicle) => {
    setSelectedVehicleId(v.id);
    setAiAdvice(null);
  };

  const handleSelectFromList = (id: string) => {
    const v = vehicles.find(veh => veh.id === id);
    if (v) handleVehicleSelect(v);
  };

  const handleOptimizeRoute = async () => {
    if (!selectedVehicleId) return;
    const v = vehicles.find(veh => veh.id === selectedVehicleId);
    if (!v) return;

    setOptimizing(true);
    const advice = await getRouteOptimization(v);
    setAiAdvice(advice);
    setOptimizing(false);
  };

  return (
    <HashRouter>
      <Layout currentTime={currentTime}>
        <Routes>
          <Route path="/" element={
            <Dashboard 
              vehicles={vehicles} 
              warehouses={MOCK_WAREHOUSES} 
              routes={INITIAL_ROUTES}
              selectedVehicleId={selectedVehicleId}
              onVehicleSelect={handleVehicleSelect}
              onVehicleListSelect={handleSelectFromList}
              aiAdvice={aiAdvice}
              optimizing={optimizing}
              onOptimizeRoute={handleOptimizeRoute}
            />
          } />
          <Route path="/map" element={
             <FleetMap 
                vehicles={vehicles}
                warehouses={MOCK_WAREHOUSES}
                routes={INITIAL_ROUTES}
                selectedVehicleId={selectedVehicleId}
                onVehicleSelect={handleVehicleSelect}
                onVehicleListSelect={handleSelectFromList}
                aiAdvice={aiAdvice}
                optimizing={optimizing}
                onOptimizeRoute={handleOptimizeRoute}
             />
          } />
          <Route path="/warehouse" element={<WarehouseOps warehouses={MOCK_WAREHOUSES} />} />
          <Route path="/analytics" element={<AnalyticsReport />} />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </Layout>
    </HashRouter>
  );
};

export default App;

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
