export enum VehicleStatus {
  ACTIVE = 'ACTIVE',
  IDLE = 'IDLE',
  DELAYED = 'DELAYED',
  MAINTENANCE = 'MAINTENANCE'
}

export interface Coordinates {
  x: number;
  y: number;
}

export interface Vehicle {
  id: string;
  name: string;
  status: VehicleStatus;
  coordinates: Coordinates;
  destination: string;
  eta: string;
  fuelLevel: number;
  cargoLoad: number; // percentage
  currentSpeed: number; // km/h
  riskScore: number; // 0-100
}

export interface Warehouse {
  id: string;
  name: string;
  coordinates: Coordinates;
  inventoryLevel: number;
  activeOrders: number;
}

export interface AIAnalysisResult {
  title: string;
  description: string;
  severity: 'low' | 'medium' | 'high';
  timestamp: string;
  recommendation?: string;
}

export interface RouteSegment {
  from: Coordinates;
  to: Coordinates;
  trafficLevel: 'low' | 'medium' | 'high';
}

import { GoogleGenAI, Type } from "@google/genai";
import { Vehicle, AIAnalysisResult } from '../types';

const API_KEY = process.env.API_KEY || '';

// Initialize Gemini
const ai = new GoogleGenAI({ apiKey: API_KEY });

export const analyzeFleetRisks = async (vehicles: Vehicle[]): Promise<AIAnalysisResult[]> => {
  if (!API_KEY) return [{
    title: "API Key Missing",
    description: "Please check your environment configuration.",
    severity: 'high',
    timestamp: new Date().toLocaleTimeString()
  }];

  try {
    const prompt = `
      Analyze the following fleet data for a logistics company.
      Identify top 3 potential risks or inefficiencies based on status, fuel, and delay indicators.
      Vehicles: ${JSON.stringify(vehicles)}

      Return a JSON array of objects with fields: title, description, severity (low, medium, high), recommendation.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        responseSchema: {
            type: Type.ARRAY,
            items: {
                type: Type.OBJECT,
                properties: {
                    title: { type: Type.STRING },
                    description: { type: Type.STRING },
                    severity: { type: Type.STRING },
                    recommendation: { type: Type.STRING }
                }
            }
        }
      }
    });

    const rawText = response.text;
    if (!rawText) throw new Error("Empty response from AI");

    const results = JSON.parse(rawText);
    return results.map((res: any) => ({
      ...res,
      timestamp: new Date().toLocaleTimeString()
    }));

  } catch (error) {
    console.error("Gemini Analysis Failed:", error);
    return [{
        title: "Analysis Failed",
        description: "Could not retrieve AI insights at this time.",
        severity: 'medium',
        timestamp: new Date().toLocaleTimeString()
    }];
  }
};

export const getRouteOptimization = async (vehicle: Vehicle): Promise<string> => {
   if (!API_KEY) return "API Key Missing.";

   try {
     const prompt = `
       Optimize route for vehicle: ${vehicle.name} (ID: ${vehicle.id}).
       Current Status: ${vehicle.status}.
       Current Location: [${vehicle.coordinates.x}, ${vehicle.coordinates.y}].
       Destination: ${vehicle.destination}.
       Fuel: ${vehicle.fuelLevel}%.

       Provide a short, tactical route recommendation in under 50 words, focusing on fuel efficiency and speed.
     `;

     const response = await ai.models.generateContent({
       model: 'gemini-2.5-flash',
       contents: prompt
     });

     return response.text || "No recommendation available.";
   } catch (error) {
     console.error("Route Optimization Failed:", error);
     return "Optimization service unavailable.";
   }
}

import React, { useState } from 'react';
import { Bot, AlertTriangle, CheckCircle, Loader2, Cpu } from 'lucide-react';
import { AIAnalysisResult, Vehicle } from '../types';
import { analyzeFleetRisks } from '../services/geminiService';

interface AIChatPanelProps {
  vehicles: Vehicle[];
}

const AIChatPanel: React.FC<AIChatPanelProps> = ({ vehicles }) => {
  const [insights, setInsights] = useState<AIAnalysisResult[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  const handleRunAnalysis = async () => {
    setIsLoading(true);
    const results = await analyzeFleetRisks(vehicles);
    setInsights(results);
    setIsLoading(false);
  };

  return (
    <div className="flex flex-col h-full bg-surface border border-gray-800 rounded-xl overflow-hidden shadow-lg">
      {/* Header */}
      <div className="p-4 border-b border-gray-800 flex items-center justify-between bg-gradient-to-r from-slate to-transparent">
        <div className="flex items-center gap-2">
          <Cpu className="w-5 h-5 text-neon" />
          <h2 className="font-display font-bold text-white tracking-wide">LOGI.AI CORE</h2>
        </div>
        <button
          onClick={handleRunAnalysis}
          disabled={isLoading}
          className={`
            px-3 py-1.5 rounded font-mono text-xs border transition-all
            ${isLoading 
              ? 'border-gray-700 text-gray-500 cursor-not-allowed' 
              : 'border-neon/30 text-neon hover:bg-neon/10 hover:shadow-[0_0_10px_#72FF72]'}
          `}
        >
          {isLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'RUN DIAGNOSTICS'}
        </button>
      </div>

      {/* Content */}
      <div className="flex-1 p-4 overflow-y-auto space-y-4">
        {insights.length === 0 && !isLoading && (
          <div className="flex flex-col items-center justify-center h-full text-gray-600 space-y-2">
            <Bot className="w-12 h-12 opacity-20" />
            <p className="text-sm font-mono">Awaiting command sequence...</p>
            <p className="text-xs text-center max-w-[200px]">Click "Run Diagnostics" to analyze fleet telemetry using Gemini 2.5 Flash.</p>
          </div>
        )}

        {insights.map((insight, idx) => (
          <div 
            key={idx} 
            className={`
              p-3 rounded border-l-2 animate-pulse-once
              ${insight.severity === 'high' ? 'bg-danger/5 border-danger' : 
                insight.severity === 'medium' ? 'bg-warning/5 border-warning' : 
                'bg-accent/5 border-accent'}
            `}
          >
            <div className="flex justify-between items-start mb-1">
              <span className={`text-xs font-bold font-mono uppercase ${
                 insight.severity === 'high' ? 'text-danger' : 
                 insight.severity === 'medium' ? 'text-warning' : 
                 'text-accent'
              }`}>
                [{insight.severity}] {insight.title}
              </span>
              <span className="text-[10px] text-gray-500 font-mono">{insight.timestamp}</span>
            </div>
            <p className="text-sm text-gray-300 mb-2 leading-relaxed">{insight.description}</p>
            {insight.recommendation && (
              <div className="mt-2 pt-2 border-t border-gray-800/50 flex items-start gap-2">
                <CheckCircle className="w-3 h-3 mt-0.5 text-neon" />
                <p className="text-xs text-neon/80 font-mono">{insight.recommendation}</p>
              </div>
            )}
          </div>
        ))}
      </div>

      {/* Input simulation (Disabled for now, this is a dashboard report style) */}
      <div className="p-3 border-t border-gray-800 bg-[#090c10]">
        <div className="text-[10px] text-gray-600 font-mono text-center">
            AI MODEL: GEMINI-2.5-FLASH // LATENCY: 45ms
        </div>
      </div>
    </div>
  );
};

export default AIChatPanel;

import React from 'react';
import { Vehicle, Warehouse, RouteSegment, VehicleStatus } from '../types';
import { MapPin, Navigation, Hexagon } from 'lucide-react';

interface MapModuleProps {
  vehicles: Vehicle[];
  warehouses: Warehouse[];
  routes: RouteSegment[];
  onVehicleSelect: (v: Vehicle) => void;
}

const MapModule: React.FC<MapModuleProps> = ({ vehicles, warehouses, routes, onVehicleSelect }) => {

  const getStatusColor = (status: VehicleStatus) => {
    switch (status) {
      case VehicleStatus.ACTIVE: return '#72FF72';
      case VehicleStatus.DELAYED: return '#FF4A4A';
      case VehicleStatus.MAINTENANCE: return '#FFB020';
      default: return '#64748B';
    }
  };

  return (
    <div className="relative w-full h-full bg-[#050708] rounded-xl overflow-hidden border border-gray-800 shadow-2xl group">
      {/* Grid Background */}
      <div className="absolute inset-0" 
           style={{ 
             backgroundImage: 'linear-gradient(#1F1F23 1px, transparent 1px), linear-gradient(90deg, #1F1F23 1px, transparent 1px)', 
             backgroundSize: '40px 40px',
             opacity: 0.3
           }}>
      </div>

      {/* Map Content */}
      <svg className="absolute inset-0 w-full h-full" viewBox="0 0 100 100" preserveAspectRatio="none">
        {/* Routes */}
        {routes.map((route, idx) => (
          <line
            key={`route-${idx}`}
            x1={route.from.x}
            y1={route.from.y}
            x2={route.to.x}
            y2={route.to.y}
            stroke={route.trafficLevel === 'high' ? '#FF4A4A' : '#1F2937'}
            strokeWidth="0.5"
            strokeDasharray={route.trafficLevel === 'low' ? "0" : "2 2"}
            className="opacity-50"
          />
        ))}

        {/* Warehouses */}
        {warehouses.map((wh) => (
          <g key={wh.id} className="cursor-pointer hover:opacity-80">
            <circle cx={wh.coordinates.x} cy={wh.coordinates.y} r="2" fill="#161B22" stroke="#38A1F7" strokeWidth="0.5" />
            <text x={wh.coordinates.x} y={wh.coordinates.y + 4} fontSize="2" fill="#38A1F7" textAnchor="middle" className="font-mono uppercase">{wh.id}</text>
          </g>
        ))}

        {/* Vehicles */}
        {vehicles.map((v) => (
          <g 
            key={v.id} 
            onClick={() => onVehicleSelect(v)}
            className="cursor-pointer transition-transform duration-300 ease-linear"
            style={{ transformOrigin: `${v.coordinates.x}% ${v.coordinates.y}%` }}
          >
             {/* Pulse Effect for Active */}
             {v.status === VehicleStatus.ACTIVE && (
                <circle cx={v.coordinates.x} cy={v.coordinates.y} r="3" fill={getStatusColor(v.status)} opacity="0.2">
                   <animate attributeName="r" from="1" to="4" dur="1.5s" repeatCount="indefinite" />
                   <animate attributeName="opacity" from="0.4" to="0" dur="1.5s" repeatCount="indefinite" />
                </circle>
             )}

             <circle cx={v.coordinates.x} cy={v.coordinates.y} r="1.2" fill={getStatusColor(v.status)} className="drop-shadow-[0_0_5px_rgba(114,255,114,0.5)]" />

             {/* Label on Hover/Group */}
             <g className="opacity-0 group-hover:opacity-100 transition-opacity duration-200">
                <rect x={v.coordinates.x + 2} y={v.coordinates.y - 2} width="15" height="4" rx="0.5" fill="#0C1114" fillOpacity="0.9" />
                <text x={v.coordinates.x + 3} y={v.coordinates.y + 0.5} fontSize="1.5" fill="white" className="font-mono">{v.id}</text>
             </g>
          </g>
        ))}
      </svg>

      {/* Overlay UI Elements */}
      <div className="absolute top-4 left-4 pointer-events-none">
         <div className="bg-slate/90 backdrop-blur border border-gray-800 p-2 rounded shadow-lg">
            <h3 className="text-xs font-display text-gray-400 uppercase tracking-wider">Live View</h3>
            <div className="flex items-center gap-2 mt-1">
               <div className="w-2 h-2 rounded-full bg-neon animate-pulse"></div>
               <span className="text-neon text-sm font-mono">SYSTEM ONLINE</span>
            </div>
         </div>
